import {chromium} from '../../.tools/browser/node_modules/playwright/index.mjs';
import {readFile,mkdir,writeFile} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
import assert from 'node:assert/strict';

// Sessions are generated by ProjectChatIT only in the isolated chat test database.
const fixture=JSON.parse(await readFile(process.env.SMARTTASK_CHAT_FIXTURE_FILE??new URL('../../.run/chat/browser-fixture.json',import.meta.url),'utf8'));
const base=process.env.SMARTTASK_CHAT_WEB_BASE??'http://127.0.0.1:5183';
assert(['127.0.0.1','localhost'].includes(new URL(base).hostname),'Only a local acceptance environment is allowed');
const output=new URL(process.env.SMARTTASK_CHAT_EVIDENCE_PATH??'../../docs/screenshots/project-chat/',import.meta.url);
await mkdir(output,{recursive:true});
const browser=await chromium.launch({channel:'msedge',headless:true});
const results=[],errors=[],latency=[];
const apiFailures=[];
const stamp=Date.now().toString().slice(-5);
async function open(account,width=1440){
  const context=await browser.newContext({viewport:{width,height:1000},timezoneId:'Asia/Bangkok',locale:'vi-VN',serviceWorkers:'block'});
  context.setDefaultTimeout(20000);
  await context.addInitScript(account=>{
    localStorage.setItem('tm.access_token',account.token);
    localStorage.setItem('tm.session_user',JSON.stringify({id:account.id,email:account.username,role:'USER',mustChangePassword:false}));
  },account);
  const page=await context.newPage();page.on('pageerror',e=>errors.push(e.message));
  page.on('response',response=>{
    const pathname=new URL(response.url()).pathname;
    if(pathname.startsWith('/api/v1/')&&response.status()>=400)
      apiFailures.push({path:pathname,status:response.status()});
  });
  await page.goto(`${base}/projects/${fixture.projectId}/chat`);
  await page.getByRole('textbox',{name:'Tin nhắn cho dự án'}).waitFor();
  await page.locator('.chat-connection').filter({hasText:'Đã kết nối'}).waitFor();
  return {page,context,account};
}
async function send(actor,text){
  await actor.page.getByRole('textbox',{name:'Tin nhắn cho dự án'}).fill(text);
  const acknowledged=actor.page.waitForResponse(r=>r.request().method()==='POST'&&new URL(r.url()).pathname.endsWith('/messages')&&r.ok());
  await actor.page.getByRole('button',{name:'Gửi tin nhắn',exact:true}).click();
  const response=await acknowledged;return (await response.json()).data;
}
async function capture(page,name){await page.locator('.project-chat').screenshot({path:fileURLToPath(new URL(name+'.png',output))});}
try{
  let ready=false;
  for(let i=0;i<40;i++){
    try{const response=await fetch(`${base}/api/v1/projects/${fixture.projectId}/chat/access`,{headers:{Authorization:`Bearer ${fixture.manager.token}`}});if(response.ok){ready=true;break;}}catch{}
    await new Promise(resolve=>setTimeout(resolve,1000));
  }
  assert(ready,'The isolated backend must be ready before browser writes');
  const first=await open(fixture.manager),second=await open(fixture.member,1280);
  const message=`Mình đã hoàn thiện phần đăng nhập, nhờ kiểm tra giúp. (${stamp})`;
  await first.page.getByRole('button',{name:'Liên kết công việc',exact:true}).click();
  await first.page.getByRole('button',{name:'Công việc liên quan',exact:true}).click();
  await first.page.getByRole('option',{name:/Kiểm tra giao diện đăng nhập/}).click();
  const start=Date.now();const original=await send(first,message);
  await second.page.getByText(message,{exact:true}).waitFor({timeout:6000});latency.push(Date.now()-start);
  assert.equal(await second.page.getByText(message,{exact:true}).count(),1);
  assert(await second.page.getByRole('link',{name:/Kiểm tra giao diện đăng nhập/}).count()>0);
  results.push('Hai tài khoản thật: gửi tin qua API, người còn lại nhận qua SSE và mở được liên kết công việc có quyền xem.');

  const reply=`Mình đã nhận được, sẽ kiểm tra trên điện thoại. (${stamp})`;
  await second.page.locator(`#chat-message-${original.id}`).getByRole('button',{name:'Trả lời',exact:true}).click();
  const secondStart=Date.now();const replyRow=await send(second,reply);
  assert.equal(replyRow.reply_to.id,original.id);
  await first.page.locator(`#chat-message-${replyRow.id}`).getByRole('button',{name:message}).click();
  assert.equal(await first.page.locator(`#chat-message-${original.id}`).evaluate(node=>node===document.activeElement),true);
  await first.page.getByText(reply,{exact:true}).waitFor({timeout:6000});latency.push(Date.now()-secondStart);
  await first.page.getByRole('textbox',{name:'Tin nhắn cho dự án'}).scrollIntoViewIfNeeded();
  await capture(first.page,'may-tinh');

  await first.page.locator(`#chat-message-${original.id}`).getByRole('button',{name:'Ghim',exact:true}).click();
  await second.page.getByRole('button',{name:new RegExp('Tin ghim')}).waitFor();
  await second.page.getByRole('textbox',{name:'Tìm tin nhắn'}).fill(stamp);
  await second.page.getByRole('button',{name:'Tìm',exact:true}).click();
  await second.page.locator('.chat-search-panel').getByRole('button',{name:message,exact:true}).click();
  await first.page.locator(`#chat-message-${original.id}`).getByRole('button',{name:'Tạo công việc',exact:true}).click();
  await first.page.getByLabel('Người phụ trách chính').selectOption(fixture.member.id);
  await first.page.getByLabel('Hạn hoàn thành (không bắt buộc)').fill('2030-02-01T10:30');
  await first.page.locator('.create-task-form').getByRole('button',{name:'Tạo công việc',exact:true}).click();
  await first.page.getByText('Đã tạo công việc',{exact:false}).waitFor();
  await first.page.getByRole('button',{name:'Đóng biểu mẫu',exact:true}).click();
  results.push('Trả lời tin gốc, ghim liên khách, tìm tin và tạo việc có hạn với người phụ trách.');

  // Both local browser contexts share the same IP quota. Give the second
  // batch its own window while leaving the production limiter active.
  await first.page.waitForTimeout(62_000);
  await second.page.goto(`${base}/projects`);
  await send(first,`@${fixture.member.username} kiểm tra thông báo ${stamp}`);
  await second.page.getByRole('link',{name:/[1-9]\d* tin chưa đọc/}).first().waitFor();
  let mention;
  for(let i=0;i<20;i++){
    const response=await second.context.request.get(`${base}/api/v1/notifications`,{headers:{Authorization:`Bearer ${fixture.member.token}`}});
    assert.equal(response.status(),200);
    mention=(await response.json()).data.items.find(row=>row.kind==='CHAT_MENTION');
    if(mention)break;
    await second.page.waitForTimeout(350);
  }
  assert(mention,'The worker must deliver the mention into the member inbox');
  await second.page.goto(`${base}/notifications`);
  const targetResponse=second.page.waitForResponse(response=>new URL(response.url()).pathname.endsWith('/target'));
  await second.page.getByRole('button',{name:'Mở trò chuyện',exact:true}).first().click();
  const target=await targetResponse;
  assert.equal(target.status(),200,`Opening mention target: ${target.status()}`);
  await second.page.waitForURL(`**/projects/${fixture.projectId}/chat`);
  await second.page.getByRole('textbox',{name:'Tin nhắn cho dự án'}).waitFor();
  results.push('Số tin chưa đọc cập nhật ngoài phòng, thông báo @nhắc mở đúng dự án.');

  const retry=`Bổ sung: đã kiểm tra bản điện thoại. (${stamp})`;
  let failOnce=true;const attempts=[];
  await second.context.route(`**/api/v1/projects/${fixture.projectId}/messages`,async route=>{
    if(route.request().method()==='POST'){
      attempts.push(route.request().postDataJSON().client_message_id);
      if(failOnce){failOnce=false;await route.abort('failed');return;}
    }
    await route.continue();
  });
  await second.page.getByRole('textbox',{name:'Tin nhắn cho dự án'}).fill(retry);
  await second.page.getByRole('button',{name:'Gửi tin nhắn',exact:true}).click();
  await second.page.getByRole('button',{name:'Thử lại tin nhắn',exact:true}).waitFor();
  assert.equal(await second.page.getByText(retry,{exact:true}).count(),1);
  await second.page.getByRole('button',{name:'Thử lại tin nhắn',exact:true}).click();
  await first.page.getByText(retry,{exact:true}).waitFor({timeout:6000});
  assert.equal(attempts.length,2);assert.equal(attempts[0],attempts[1]);
  assert.equal(await second.page.getByText(retry,{exact:true}).count(),1);
  results.push('Lỗi mạng: bản tin được giữ để thử lại, dùng cùng định danh và chỉ xuất hiện một lần.');

  const unreadUrl=`${base}/api/v1/projects/${fixture.projectId}/chat/unread`;
  await first.page.getByRole('textbox',{name:'Tin nhắn cho dự án'}).scrollIntoViewIfNeeded();
  await first.page.locator('.chat-messages').evaluate(node=>{node.scrollTop=node.scrollHeight;node.dispatchEvent(new Event('scroll'));});
  let unread;
  for(let i=0;i<30;i++){
    unread=(await (await first.context.request.get(unreadUrl,{headers:{Authorization:`Bearer ${fixture.manager.token}`}})).json()).data;
    if(unread.count===0)break;await new Promise(resolve=>setTimeout(resolve,100));
  }
  assert.equal(unread.count,0);results.push('Dấu đã đọc được lưu ở server khi người dùng xem đến cuối cuộc trao đổi.');

  const deletedBefore=await first.page.getByText('Tin nhắn đã được xóa',{exact:true}).count();
  const replyArticle=second.page.locator('article.chat-message').filter({has:second.page.getByText(reply,{exact:true})});
  await replyArticle.getByRole('button',{name:/Xóa tin của/}).click();
  await second.page.getByRole('button',{name:'Xác nhận xóa tin',exact:true}).click();
  await first.page.getByText(reply,{exact:true}).waitFor({state:'hidden',timeout:6000});
  assert.equal(await first.page.getByText('Tin nhắn đã được xóa',{exact:true}).count(),deletedBefore+1);
  const history=await first.context.request.get(`${base}/api/v1/projects/${fixture.projectId}/messages`,{headers:{Authorization:`Bearer ${fixture.manager.token}`}});
  const tombstone=(await history.json()).data.items.find(row=>row.id===replyRow.id);
  assert.equal(tombstone.deleted,true);assert.equal(tombstone.body,null);
  results.push('Xóa tin của chính mình cần xác nhận; người còn lại thấy dấu đã xóa và API không trả nội dung cũ.');

  await first.context.setOffline(true);
  const missed=`Tin được gửi khi người kia mất mạng. (${stamp})`;
  await send(second,missed);
  assert.equal(await first.page.getByText(missed,{exact:true}).count(),0);
  await first.context.setOffline(false);
  await first.page.getByText(missed,{exact:true}).waitFor({timeout:10000});
  results.push('Mất mạng rồi kết nối lại: tải bù đủ tin từ PostgreSQL, không phải tải lại trang.');

  await second.page.setViewportSize({width:390,height:844});
  await second.page.getByRole('textbox',{name:'Tin nhắn cho dự án'}).scrollIntoViewIfNeeded();
  assert.equal(await second.page.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1),false);
  await capture(second.page,'dien-thoai');

  const secret=`Bản nháp phải được xóa khi mất quyền ${stamp}`;
  await second.page.getByRole('textbox',{name:'Tin nhắn cho dự án'}).fill(secret);
  const removed=await first.context.request.delete(`${base}/api/v1/projects/${fixture.projectId}/members/${fixture.member.id}`,{headers:{Authorization:`Bearer ${fixture.manager.token}`}});
  assert.equal(removed.status(),200);
  await second.page.getByRole('textbox',{name:'Tin nhắn cho dự án'}).waitFor({state:'hidden',timeout:10000});
  assert.equal(await second.page.evaluate(text=>Object.values(localStorage).some(value=>value.includes(text)),secret),false);
  const denied=await second.context.request.get(`${base}/api/v1/projects/${fixture.projectId}/messages`,{headers:{Authorization:`Bearer ${fixture.member.token}`}});
  assert.equal(denied.status(),404);
  results.push('Gỡ thành viên khi đang chat: giao diện đóng phòng, bản nháp không lưu vào localStorage và API trả 404.');

  assert.deepEqual(errors,[]);
  const evidence={mode:'Hai phiên Edge, backend và PostgreSQL thử nghiệm cục bộ',results,latency_ms:latency,note:'Hai mẫu quan sát khi nghiệm thu, không phải benchmark hoặc p95.',errors};
  await writeFile(new URL('ket-qua.json',output),JSON.stringify(evidence,null,2));console.log(JSON.stringify(evidence,null,2));
  await first.context.close();await second.context.close();
}catch(error){
  console.error(JSON.stringify({passed:results,apiFailures,errors},null,2));
  throw error;
}finally{await browser.close();}
